    "id": "JAH-NMK-000001",
    "name": "Min-jun 민준",
    "kind": "first-name",
    "meaning": "Min-jun (민준) is a masculine given name in Korean. Meaning: Clever + handsome. Meaning fixed by the hanja chosen; a top b"
}
