    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Min")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

